<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from "vue";
import { Plus, Search } from "lucide-vue-next";
import PlaylistRow from "./PlaylistRow.vue";
import { usePlaylistStore } from "../stores/playlists";
import { useLibraryStore } from "../stores/library";

type Change = "add" | "remove";
const props = defineProps<{ trackPath: string; anchor: HTMLElement }>();
const emit = defineEmits<{ close: []; toast: [message: string] }>();
const playlists = usePlaylistStore(); const library = useLibraryStore();
const popover = ref<HTMLElement | null>(null); const input = ref<HTMLInputElement | null>(null); const query = ref(""); const showForm = ref(false); const name = ref(""); const error = ref(""); const changes = ref(new Map<string, Change>());
const original = new Set(playlists.playlists.filter(p => p.trackPaths.includes(props.trackPath)).map(p => p.id));
const filtered = computed(() => playlists.playlists.filter(p => p.name.toLowerCase().includes(query.value.toLowerCase())).sort((a,b) => b.updatedAt - a.updatedAt));
const saved = computed(() => filtered.value.filter(p => original.has(p.id)));
const others = computed(() => filtered.value.filter(p => !original.has(p.id)));
const hasResults = computed(() => filtered.value.length > 0);

function isSaved(id: string) { return changes.value.get(id) === "add" || (original.has(id) && changes.value.get(id) !== "remove"); }
function toggle(id: string) { const next = isSaved(id) ? "remove" : "add"; changes.value.set(id, next); }
function create() { const value = name.value.trim(); if (!value) { error.value = "Name is required"; return; } if (playlists.nameExists(value)) { error.value = "Playlist already exists"; return; } playlists.createPlaylist(value).then(p => { changes.value.set(p.id, "add"); name.value = ""; showForm.value = false; }); }
async function apply() { for (const [id, action] of changes.value) action === "add" ? await playlists.addTrack(id, props.trackPath) : await playlists.removeTrack(id, props.trackPath); emit("toast", "Playlists updated"); emit("close"); }
function cancel() { emit("close"); }
function position() { if (!popover.value) return; const r = props.anchor.getBoundingClientRect(); const below = r.bottom + 8; const height = Math.min(560, window.innerHeight - 32); popover.value.style.left = `${Math.min(r.left, window.innerWidth - 376)}px`; popover.value.style.top = `${below + height > window.innerHeight - 16 ? Math.max(16, r.top - height - 8) : below}px`; }
function outside(e: MouseEvent) { if (popover.value && !popover.value.contains(e.target as Node) && !props.anchor.contains(e.target as Node)) cancel(); }
function key(e: KeyboardEvent) { if (e.key === "Escape") cancel(); }
onMounted(async () => { await playlists.initStore(); showForm.value = !playlists.playlists.length; await nextTick(); input.value?.focus(); position(); window.addEventListener("mousedown", outside); window.addEventListener("keydown", key); window.addEventListener("resize", position); });
onUnmounted(() => { window.removeEventListener("mousedown", outside); window.removeEventListener("keydown", key); window.removeEventListener("resize", position); });
</script>
<template><Teleport to="body"><div ref="popover" class="popover"><h3>Add to playlist</h3><label class="search-box"><Search :size="16"/><input ref="input" v-model="query" placeholder="Find a playlist"/></label><button v-if="!showForm" class="new-row" @click="showForm = true"><Plus :size="18"/> New playlist</button><div v-else class="create-form"><input v-model="name" placeholder="Playlist name" @keyup.enter="create"/><button @click="create">Create</button><small v-if="error">{{ error }}</small></div><div class="divider"/><div v-if="!playlists.playlists.length" class="empty">Belum ada playlist. Buat yang pertama di atas.</div><div v-else-if="!hasResults" class="empty">Tidak ada playlist dengan nama “{{ query }}”.</div><div v-else class="playlist-list" role="listbox" aria-multiselectable="true"><template v-if="saved.length"><h4>Saved in</h4><PlaylistRow v-for="p in saved" :key="p.id" :playlist="p" :track-path="trackPath" :tracks="p.trackPaths.map(id => library.tracks.find(t => t.path === id)).filter(Boolean) as never[]" :saved="isSaved(p.id)" @toggle="toggle(p.id)"/></template><template v-if="others.length"><h4>Recently updated</h4><PlaylistRow v-for="p in others" :key="p.id" :playlist="p" :track-path="trackPath" :tracks="p.trackPaths.map(id => library.tracks.find(t => t.path === id)).filter(Boolean) as never[]" :saved="isSaved(p.id)" @toggle="toggle(p.id)"/></template></div><footer><button @click="cancel">Cancel</button><button v-if="changes.size" class="done" @click="apply">Done</button></footer></div></Teleport></template>
<style scoped>
.popover{position:fixed;width:360px;max-height:min(560px,calc(100vh - 32px));display:flex;flex-direction:column;gap:12px;padding:16px;background:var(--surface-bg);border-radius:24px;box-shadow:var(--shadow-raised);overflow:hidden;z-index:100}.popover h3{margin:0;color:var(--text-secondary);font-size:13px;font-weight:700}.search-box{display:flex;align-items:center;gap:8px;padding:11px 12px;border-radius:14px;background:var(--surface-bg);box-shadow:var(--shadow-inset);color:var(--text-secondary)}.search-box:focus-within{box-shadow:var(--shadow-inset),0 0 0 2px rgba(255,106,0,.35)}.search-box input,.create-form input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:var(--text-primary)}.new-row{display:flex;align-items:center;gap:8px;padding:9px;border:0;border-radius:12px;background:transparent;color:var(--accent);cursor:pointer;font-weight:600}.new-row:hover{background:var(--surface-bg);box-shadow:var(--shadow-raised-sm)}.create-form{display:grid;grid-template-columns:1fr auto;gap:8px}.create-form input{padding:10px;border-radius:12px;box-shadow:var(--shadow-inset)}.create-form button,.done{border:0;border-radius:12px;padding:0 14px;background:linear-gradient(145deg,#ff8a33,#e55a00);color:#fff;cursor:pointer;font-weight:700}.create-form small{grid-column:1/-1;color:#ff8c66}.divider{height:2px;background:#171717;box-shadow:0 1px 0 rgba(255,255,255,.05);flex:none}.playlist-list{min-height:0;overflow-y:auto;padding:2px 4px}.playlist-list h4{margin:8px 4px 4px;color:var(--text-secondary);font-size:10px;text-transform:uppercase;letter-spacing:.1em}.empty{padding:24px 10px;text-align:center;color:var(--text-secondary);font-size:12px}footer{display:flex;justify-content:flex-end;gap:8px;margin:0 -16px -16px;padding:12px 16px;background:rgba(0,0,0,.08)}footer button{border:0;background:transparent;color:var(--text-secondary);padding:8px 12px;border-radius:10px;cursor:pointer}footer button:hover{color:var(--text-primary);box-shadow:var(--shadow-raised-sm)}footer .done{color:#fff}
</style>
